		size          int
		square        bool
		width, height int
		format        string
	}{
		{40, false, 40, 20, "jpeg"},
		{40, true, 40, 40, "png"},
		{100, true, 80, 80, "png"},
		{0, true, 80, 80, "png"},
	} {
		result, _, err := resizeImage(bytes.NewReader(source.Bytes()), tc.size, tc.square)
		if err != nil {
			t.Fatal(err)
		}
		decoded, format, err := image.Decode(result)
		if err != nil {
			t.Fatal(err)
		}
		if decoded.Bounds().Dx() != tc.width || decoded.Bounds().Dy() != tc.height || format != tc.format {
			t.Errorf("size %d square %t: got %dx%d %s", tc.size, tc.square, decoded.Bounds().Dx(), decoded.Bounds().Dy(), format)
		}
		if tc.square {
			if _, ok := result.(*bytes.Buffer); !ok {
				t.Error("square result should be encoded")
			}
		}
	}
